+      const index = this.undoStack.indexOf(trn);
+      if (index != -1) {
+        this.undoStack.splice(index, 1);
+      }
+
+      throw error;
+    }
   }

   /**
@@ -194,12 +257,27 @@ export class CalBatchTransaction extends CalTransaction {
   transactions = [];

