     this.transactions.push(trn);
-    return trn.doTransaction();
+
+    try {
+      return await trn.doTransaction();
+    } catch (error) {
+      // Other batch members can finish before this failure reaches the caller.
+      const index = this.transactions.indexOf(trn);
+      if (index != -1) {
+        this.transactions.splice(index, 1);
+      }
+
+      throw error;
+    }
   }

   canWrite() {
@@ -296,7 +374,27 @@ export class CalAddTransaction extends CalBaseTransaction {
  * CalModifyTransaction handles modifications.
  */
 export class CalModifyTransaction extends CalBaseTransaction {
+  /**
+   * Applies an edit or move and sends its scheduling messages.
+   *
+   * If source deletion fails during a move, removes the unchanged destination
+   * copy and rethrows the source error. Preserves copies changed by other edits.
+   * Logs cleanup failures and retains each failed copy for cleanup on retry.
+   * Before another edit, removes unchanged copies left by failed moves for the
+   * same source item.
+   *
+   * @returns {Promise<void>} Resolves after storage and notifications finish.
+   * @throws If the calendar edit or move fails.
+   */
   async doTransaction() {
+    const recoveryKey = JSON.stringify([this.oldItem.calendar.id, this.oldItem.id]);
+
+    // Only await cleanup when a failed move left a record. Without recovery,
+    // memory-calendar edits must still reach modifyItem before the first pause.
+    if (pendingMoveCopies.has(recoveryKey)) {
+      await removePendingMoveCopies(recoveryKey);
+    }
+
     let item;
     if (this.item.calendar.id == this.oldItem.calendar.id) {
       item = await this.calendar.modifyItem(
@@ -307,10 +405,40 @@ export class CalModifyTransaction extends CalBaseTransaction {
     } else {
       this.oldCalendar = this.oldItem.calendar;
       item = await this.calendar.addItem(this.item);
+
+      // Retain the exact added revision. Later provider or editor changes must
+      // not change the values used to decide whether cleanup can delete it.
+      const copy = item.clone();
+      copy.makeImmutable();
+
+      try {
+        await this.oldItem.calendar.deleteItem(this.oldItem);
+      } catch (error) {
+        // Record the copy before cleanup. If cleanup fails too, the next edit
+        // of this source item can retry even though this transaction failed.
+        const copies = pendingMoveCopies.get(recoveryKey) ?? new Set();
+        copies.add(copy);
+        pendingMoveCopies.set(recoveryKey, copies);
+
+        try {
+          await removePendingMoveCopies(recoveryKey);
+        } catch (rollbackError) {
+          console.error(
+            "Could not remove the destination copy of a failed calendar move",
+            rollbackError
+          );
+        }
+
+        // Cleanup failure must not replace the source deletion error.
+        throw error;
+      }
+
+      // Send invitations or cancellations only after both move operations
+      // succeed. A failed move must not announce an incomplete change.
       this._dispatch(Ci.calIOperationListener.ADD, item, this.oldItem);
-      await this.oldItem.calendar.deleteItem(this.oldItem);
       this._dispatch(Ci.calIOperationListener.DELETE, this.oldItem, this.oldItem);
     }
+
     this.item = item;
   }

diff --git a/calendar/providers/storage/CalStorageCachedItemModel.sys.mjs b/calendar/providers/storage/CalStorageCachedItemModel.sys.mjs
index e6294702047..a7dcb589328 100644
--- a/calendar/providers/storage/CalStorageCachedItemModel.sys.mjs
+++ b/calendar/providers/storage/CalStorageCachedItemModel.sys.mjs
@@ -200,6 +200,30 @@ export class CalStorageCachedItemModel extends CalStorageItemModel {
     this.#recurringTodosCache.delete(id);
   }

+  /**
+   * Removes cached items only after storage deletes the expected revision.
+   *
+   * @param {calIItemBase} item - The expected whole item and revision.
+   * @returns {Promise<boolean>} True if storage deleted the matching item.
+   * @throws If a storage statement fails.
+   */
+  async deleteItemIfUnchanged(item) {
+    // This entry remains the reference for the cache check until storage
+    // completes. Another write can replace the entry while deletion is pending.
+    const cached = this.itemCache.get(item.id);
+    const deleted = await super.deleteItemIfUnchanged(item);
+
+    // Remove cached values only for a successful deletion whose cache entry
+    // has not been replaced. A rejected deletion must preserve all caches.
+    if (deleted && this.itemCache.get(item.id) === cached) {
+      this.itemCache.delete(item.id);
+      this.#recurringEventsCache.delete(item.id);
+      this.#recurringTodosCache.delete(item.id);
+    }
+
+    return deleted;
+  }
+
   /**
    * Overridden here to empty the item caches along with the database. The
    * offline flag caches are left alone on purpose - nothing refills them.
diff --git a/calendar/providers/storage/CalStorageCalendar.sys.mjs b/calendar/providers/storage/CalStorageCalendar.sys.mjs
index 983be913ce8..fb7be745bae 100644
--- a/calendar/providers/storage/CalStorageCalendar.sys.mjs
+++ b/calendar/providers/storage/CalStorageCalendar.sys.mjs
@@ -389,6 +389,37 @@ CalStorageCalendar.prototype = {
     return null;
   },

+  /**
+   * Deletes a failed-move copy only if its stored revision still matches.
+   * Does not send deletion notifications for a missing or changed item.
+   *
+   * @param {calIItemBase} item - The whole item checked by failed-move cleanup.
+   * @returns {Promise<boolean>} True if storage deleted the matching item.
+   * @throws If the calendar is read-only, the item is invalid, or deletion fails.
+   */
+  async deleteItemIfUnchanged(item) {
+    if (this.readOnly) {
+      throw new Components.Exception("Calendar is readonly", Ci.calIErrors.CAL_IS_READONLY);
+    }
+
+    // Recovery removes an entire destination copy. An occurrence would need
+    // changes to its parent item instead of deletion of the stored series.
+    if (item.id == null || item.parentItem != item) {
+      throw new Components.Exception("Expected a whole item with an ID", Cr.NS_ERROR_INVALID_ARG);
+    }
+
+    if (!(await this.mItemModel.deleteItemIfUnchanged(item))) {
+      // A missing item or a newer revision is not a deletion. Keep observers
+      // unchanged so they retain any copy that another editor saved.
+      return false;
+    }
+
+    this.notifyOperationComplete(null, Cr.NS_OK, Ci.calIOperationListener.DELETE, item.id, item);
+    this.observers.notify("onDeleteItem", [item]);
+
+    return true;
+  },
+
   // Promise<calIItemBase|null> getItem(in string id);
   async getItem(aId) {
     return this.mItemModel.getItemById(aId);
diff --git a/calendar/providers/storage/CalStorageItemModel.sys.mjs b/calendar/providers/storage/CalStorageItemModel.sys.mjs
index 2d3c8ae8195..3925493c04e 100644
--- a/calendar/providers/storage/CalStorageItemModel.sys.mjs
+++ b/calendar/providers/storage/CalStorageItemModel.sys.mjs
@@ -1359,6 +1359,53 @@ export class CalStorageItemModel extends CalStorageModelBase {
     return CAL_ITEM_FLAG.HAS_ALARMS;
   }

+  /**
+   * Deletes an item and its auxiliary rows if the stored revision matches.
+   * Runs all statements in one storage batch so another write cannot occur
+   * between the revision check and deletion.
+   *
+   * @param {calIItemBase} item - The expected whole item and revision.
+   * @returns {Promise<boolean>} True after the matching item is deleted. False
+   *   if the item is missing or its revision differs. Resolves after storage
+   *   completes the batch.
+   * @throws If a storage statement fails.
+   */
+  async deleteItemIfUnchanged(item) {
+    const statements = item.isEvent()
+      ? this.statements.mDeleteEventIfUnchanged
+      : this.statements.mDeleteTodoIfUnchanged;
+
+    // Each deletion checks the same captured revision. Bind every statement
+    // before submission so the batch needs no intermediate JavaScript reads.
+    const stmts = [];
+    for (const statement of statements) {
+      this.db.prepareItemStatement(stmts, statement, "id", item.id);
+      statement.params.generation = item.generation;
+      statement.params.last_modified = item.lastModifiedTime?.nativeTime ?? null;
+      statement.params.stamp = item.stampTime?.nativeTime ?? null;
+      statement.params.time_created = item.getProperty("CREATED")?.nativeTime ?? null;
+    }
+
+    // Read the master deletion's count before deleting properties. The
+    // property deletion uses that same count to preserve a newer item's rows.
+    stmts.push(this.statements.mSelectDeleteItemResult);
+    this.db.prepareItemStatement(
+      stmts,
+      this.statements.mDeletePropertiesIfItemDeleted,
+      "item_id",
+      item.id
+    );
+
+    // Submit the ordered statements together. Separate submissions would allow
+    // another write between the revision checks and the remaining deletions.
+    let deleted = false;
+    await this.db.executeAsync(stmts, row => {
+      deleted = row.getResultByName("deleted") > 0;
+    });
+
+    return deleted;
+  }
+
   /**
    * Deletes the item with the given item id.
    *
diff --git a/calendar/providers/storage/CalStorageStatements.sys.mjs b/calendar/providers/storage/CalStorageStatements.sys.mjs
