   mDeleteTodo = null;

+  /** @type {mozIStorageAsyncStatement[]} Revision-checked event deletions. */
+  mDeleteEventIfUnchanged = [];
+
+  /** @type {mozIStorageAsyncStatement[]} Revision-checked task deletions. */
+  mDeleteTodoIfUnchanged = [];
+
+  /** @type {mozIStorageAsyncStatement} The preceding master deletion's count. */
+  mSelectDeleteItemResult = null;
+
+  /** @type {mozIStorageAsyncStatement} Property deletion after a master deletion. */
+  mDeletePropertiesIfItemDeleted = null;
+
   /**
    * @type {mozIStorageAsyncStatement}
    */
@@ -687,6 +699,63 @@ export class CalStorageStatements {
       "DELETE FROM cal_alarms WHERE item_id = :item_id AND cal_id = :cal_id"
     );

+    for (const [table, stamp, statements] of [
+      ["cal_events", "event_stamp", this.mDeleteEventIfUnchanged],
+      ["cal_todos", "todo_stamp", this.mDeleteTodoIfUnchanged],
+    ]) {
+      // The master row has no recurrence ID. Compare its revision with the
+      // cleanup snapshot. IS treats two NULL timestamps as equal. A missing
+      // X-MOZ-GENERATION property defaults to zero, as the item getter does.
+      const revisionMatches = `EXISTS (
+        SELECT 1 FROM ${table}
+         WHERE cal_id = :cal_id AND id = :id AND recurrence_id IS NULL
+           AND last_modified IS :last_modified AND ${stamp} IS :stamp
+           AND time_created IS :time_created
+      ) AND COALESCE((
+        SELECT CAST(value AS INTEGER) FROM cal_properties
+         WHERE cal_id = :cal_id AND item_id = :id AND recurrence_id IS NULL
+           AND key = 'X-MOZ-GENERATION'
+      ), 0) = :generation`;
+
+      // Every related-row deletion needs the master and generation property
+      // for its revision check. Delete those two sources only after these rows.
+      for (const extra of [
+        "cal_attendees",
+        "cal_parameters",
+        "cal_recurrence",
+        "cal_attachments",
+        "cal_relations",
+        "cal_metadata",
+        "cal_alarms",
+      ]) {
+        statements.push(
+          db.createAsyncStatement(
+            `DELETE FROM ${extra}
+              WHERE item_id = :id AND cal_id = :cal_id AND ${revisionMatches}`
+          )
+        );
+      }
+
+      // Removing the master last leaves its deletion count available to the
+      // result query. A revision mismatch leaves the entire item unchanged.
+      statements.push(
+        db.createAsyncStatement(
+          `DELETE FROM ${table}
+            WHERE id = :id AND cal_id = :cal_id AND ${revisionMatches}`
+        )
+      );
+    }
+
+    this.mSelectDeleteItemResult = db.createAsyncStatement("SELECT changes() AS deleted");
+
+    // SELECT does not change changes(). It still reports the master deletion.
+    // Remove properties only when that deletion succeeded; their generation
+    // value was needed by all preceding revision checks.
+    this.mDeletePropertiesIfItemDeleted = db.createAsyncStatement(
+      `DELETE FROM cal_properties
+        WHERE item_id = :item_id AND cal_id = :cal_id AND changes() > 0`
+    );
+
     // These are only used when deleting an entire calendar
     const extrasTables = [
       "cal_attendees",
@@ -743,5 +812,11 @@ export class CalStorageStatements {
     for (const stmt of this.mDeleteTodoExtras) {
       stmt.finalize();
     }
+
+    // The first loop visits only statements stored directly on this object.
+    // Finalize statements stored in arrays separately.
+    for (const stmt of [...this.mDeleteEventIfUnchanged, ...this.mDeleteTodoIfUnchanged]) {
+      stmt.finalize();
+    }
   }
 }
