+/** Failed commits do not leave failed transactions among successful edits. */
+add_task(async function test_failedCommitsLeaveOtherTransactions() {
+  for (const batch of [false, true]) {
+    const manager = new CalTransactionManager();
+    const owner = batch ? manager.beginBatch() : manager;
+    const first = new MockCalTransaction();
+    const last = new MockCalTransaction();
+    await owner.commit(first);
+
+    // Keep one commit pending while a later commit succeeds. Failure must
+    // remove the pending transaction without removing the later transaction.
+    const started = Promise.withResolvers();
+    const finish = Promise.withResolvers();
+    const failed = new MockCalTransaction();
+    failed.doTransaction = async () => {
+      started.resolve();
+      await finish.promise;
+      throw new Error("Commit failed");
+    };
+
+    const pending = owner.commit(failed);
+    await started.promise;
+    await owner.commit(last);
+    finish.resolve();
+
+    await Assert.rejects(pending, /Commit failed/);
+    Assert.deepEqual(
+      batch ? owner.transactions : manager.undoStack,
+      [first, last],
+      "Failure should remove only the failed edit, even when another edit finishes first."
+    );
+
+    await manager.undo();
+
+    Assert.equal(last.undone, 1);
+
+    if (!batch) {
+      await manager.undo();
+    }
+
+    Assert.equal(first.undone, 1);
+    Assert.equal(failed.undone, 0, "Undo should not run a failed transaction.");
+
+    if (!batch) {
+      await manager.redo();
+    }
+    await manager.redo();
+
+    Assert.equal(first.done, 2);
+    Assert.equal(last.done, 2);
+  }
+});
+
+add_task(async function test_modifyMemoryItemsStartsBeforeYield() {
+  const calendar = CalendarTestUtils.createCalendar("Immediate edits", "memory");
+  registerCleanupFunction(() => CalendarTestUtils.removeCalendar(calendar));
+  let modifiedItem;
+  /** @implements {calIObserver} */
+  const observer = {
+    QueryInterface: ChromeUtils.generateQI(["calIObserver"]),
+    onStartBatch() {},
+    onEndBatch() {},
+    onLoad() {},
+    onAddItem() {},
+    onModifyItem(item) {
+      modifiedItem = item;
+    },
+    onDeleteItem() {},
+    onError(unusedCalendar, code, message) {
+      Assert.ok(false, `The calendar should report no error; received ${code}: ${message}`);
+    },
+    onPropertyChanged() {},
+    onPropertyDeleting() {},
+  };
+  calendar.addObserver(observer);
+  registerCleanupFunction(() => calendar.removeObserver(observer));
+
+  for (const Item of [CalEvent, CalTodo]) {
+    const original = await calendar.addItem(new Item());
+    const edited = original.clone();
+    edited.title = "Edited";
+    const transaction = new CalModifyTransaction(edited, calendar, original, null);
+    transaction._dispatch = () => {};
+    const manager = new CalTransactionManager();
+
+    // Inspect the observer result before awaiting commit or redo. An added
+    // initial await would delay the memory provider notification until later.
+    modifiedItem = null;
+    const committed = manager.commit(transaction);
+
+    Assert.ok(modifiedItem, "Memory-calendar edits should notify observers before yielding.");
+    Assert.equal(modifiedItem.title, "Edited");
+
+    await committed;
+    await manager.undo();
+    modifiedItem = null;
+    const redone = manager.redo();
+
+    Assert.ok(modifiedItem, "Redo should notify observers before yielding.");
+    Assert.equal(modifiedItem.title, "Edited");
+
+    await redone;
+    await calendar.deleteItem(modifiedItem);
+  }
+});
+
+/** Tests that cleanup failure preserves the source deletion error. */
+add_task(async function test_moveRollbackFailureKeepsSourceError() {
+  const source = CalendarTestUtils.createCalendar("Source", "memory");
+  const destination = CalendarTestUtils.createCalendar("Destination", "memory");
+  const sourceCalendar = source.wrappedJSObject;
+  const destinationCalendar = destination.wrappedJSObject;
+  const sourceDelete = sourceCalendar.deleteItem;
+  const destinationDelete = destinationCalendar.deleteItem;
+  const sourceError = new Error("Source deletion failed");
+  const rollbackError = new Error("Destination rollback failed");
+  const event = new CalEvent();
+  event.id = "failed-move";
+  event.title = "Source";
+  const original = await source.addItem(event);
+  const moved = original.clone();
+  moved.calendar = destination;
+  moved.title = "Destination";
+  const transaction = new CalModifyTransaction(moved, destination, original, null);
+  let notifications = 0;
+  transaction._dispatch = () => notifications++;
+  const manager = new CalTransactionManager();
+
+  // Simulate source deletion and cleanup failing. The caller must still receive
+  // the source error, and Undo must not contain the failed move.
+  sourceCalendar.deleteItem = async () => {
+    throw sourceError;
+  };
+  destinationCalendar.deleteItem = async () => {
+    throw rollbackError;
+  };
+  try {
+    let failure;
+    try {
+      await manager.commit(transaction);
+    } catch (error) {
+      failure = error;
+    }
+
+    Assert.equal(
+      failure,
+      sourceError,
+      "Rollback failure should not hide the source deletion error."
+    );
+    Assert.equal(notifications, 0, "Incomplete moves should send no notifications.");
+    Assert.equal(manager.undoStack.length, 0, "Failed moves should leave no Undo transaction.");
+    Assert.equal((await source.getItem(event.id)).title, "Source");
+  } finally {
+    sourceCalendar.deleteItem = sourceDelete;
+    destinationCalendar.deleteItem = destinationDelete;
+    CalendarTestUtils.removeCalendar(source);
+    CalendarTestUtils.removeCalendar(destination);
