+      info(`Axe completed ${report.runCount} checks`);
+    }
+    dialog.close();
+    tabmail.closeTab(tab);
+    CalendarTestUtils.removeCalendar(calendar);
+    CalendarTestUtils.removeCalendar(otherCalendar);
+  });
+});
