+add_task(async function test_moveRollbackPreservesEditsAfterCleanupRead() {
+  // Change the destination after cleanup captures its snapshot. A content
+  // comparison alone cannot protect an edit made during this interval.
+  const {
+    storage,
+    sourceProvider,
+    targetProvider,
+    sourceDelete,
+    targetGet,
+    notifications,
+    restore,
+  } = setupMoveRecovery();
+  const deletions = [];
+  const observer = { onDeleteItem: item => deletions.push(item.id) };
+  registerCleanupFunction(() => storage.removeObserver(observer));
+  storage.addObserver(observer);
+
+  for (const change of ["content", "revision"]) {
+    const original = await createEvent(true);
+    await startEdit(original);
+    changeTitle("Move draft");
+    changeCalendar(storage);
+    const undoStack = [...manager.undoStack];
+    const redoStack = [...manager.redoStack];
+    let updated;
+    sourceProvider.deleteItem = async () => {
+      throw new Error("Source deletion failed");
+    };
+    targetProvider.getItem = async function (id) {
+      const snapshot = await targetGet.call(this, id);
+      if (snapshot && !updated) {
+        // Return the old snapshot after another editor saves a new revision.
+        const changed = snapshot.clone();
+        if (change == "content") {
+          changed.title = "Another editor's title";
+          changed.setProperty("LOCATION", "Another editor's room");
+        }
+        updated = await storage.modifyItem(changed, snapshot);
+
+        Assert.greater(
+          updated.generation,
+          snapshot.generation,
+          "The edit after the cleanup read should advance the stored revision."
+        );
+      }
+      return snapshot;
+    };
+    notifications.length = 0;
+    deletions.length = 0;
+
+    Assert.equal(
+      (await save()).status,
+      "error",
+      "Save should report an error for the failed move."
+    );
+
+    targetProvider.getItem = targetGet;
+    sourceProvider.deleteItem = sourceDelete;
+
+    Assert.ok(
+      updated,
+      "Another edit should finish after cleanup captures the snapshot."
+    );
+    Assert.deepEqual(
+      deletions,
+      [],
+      "Cleanup should send no deletion notification."
+    );
+    Assert.deepEqual(
+      notifications,
+      [],
+      "The failed move should send no scheduling messages."
+    );
+    Assert.deepEqual(
+      manager.undoStack,
+      undoStack,
+      "The failed move should preserve Undo."
+    );
+    Assert.deepEqual(
+      manager.redoStack,
+      redoStack,
+      "The failed move should preserve Redo."
+    );
+
+    const cached = await storage.getItem(original.id);
+
+    Assert.ok(
+      cached && cal.item.compareContent(cached, updated, [], {}),
+      "Cleanup should preserve the newer cached item."
+    );
+    // Bypass the item cache to check the database rows as well as the cache.
+    targetProvider.mItemModel.itemCache.delete(original.id);
+    const stored = await storage.getItem(original.id);
+
+    Assert.ok(
+      stored && cal.item.compareContent(stored, updated, [], {}),
+      "Cleanup should preserve the newer item and its auxiliary rows in storage."
+    );
+    Assert.equal(
+      selectCalendarEventDraftState(store.getState(), sessionKey).value.title,
+      "Move draft",
+      "The failed move should retain the entered title."
+    );
+    Assert.equal(
+      (await saveWithDuplicateId(storage)).status,
+      "error",
+      "Retry should not replace the other editor's destination item."
+    );
+
+    changeCalendar(calendar);
+
+    Assert.equal(
+      (await save()).status,
+      "success",
+      "The retained draft should save in its source."
+    );
+    Assert.equal(
+      (await calendar.getItem(original.id)).title,
+      "Move draft",
+      "Retry should save the retained source title."
+    );
+    Assert.ok(
+      cal.item.compareContent(
+        await storage.getItem(original.id),
+        updated,
+        [],
+        {}
+      ),
+      "Retry should preserve the other editor's destination item."
+    );
+  }
+  restore();
+});
